text:
{
  "table": {
    "name": "rulings",
    "purpose": "MTG card rulings: official rules clarifications/Oracle rulings for individual cards, with the date the ruling was issued and a reference to the card it applies to."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "ruling_id",
      "description": "Primary key; sequential integer ID of the ruling row.",
      "status": "resolved"
    },
    "col_002": {
      "role": "date",
      "name": "ruling_date",
      "description": "Date the ruling was published/issued (range 2004-10-04 to 2021-02-05).",
      "status": "resolved"
    },
    "col_003": {
      "role": "free_text",
      "name": "ruling_text",
      "description": "Text of the official ruling explaining how the card's rules work.",
      "status": "resolved"
    },
    "col_004": {
      "role": "foreign_key",
      "name": "card_uuid",
      "description": "UUID of the card the ruling applies to; references cards.col_072 (card UUID).",
      "status": "resolved"
    }
  }
}
